#!/usr/bin/env node

const { execFileSync } = require("node:child_process");
const { writeFileSync } = require("node:fs");
const { join } = require("node:path");

const projectRoot = join(__dirname, "..");
const outputPath = join(projectRoot, "src", "git-hash.ts");

const gitHash =
    normalize(process.env.CONDUIT_BUILD_GIT_HASH) ??
    normalize(process.env.CI_COMMIT_SHORT_SHA) ??
    normalize(process.argv[2]) ??
    readGitHash(projectRoot) ??
    "unknown";

writeFileSync(
    outputPath,
    [
        "// @generated by scripts/write-git-hash.js",
        `export const GIT_HASH = ${JSON.stringify(gitHash)};`,
        "",
    ].join("\n"),
);

function normalize(value) {
    if (typeof value !== "string") {
        return undefined;
    }
    const trimmed = value.trim();
    return trimmed.length > 0 ? trimmed : undefined;
}

function readGitHash(cwd) {
    try {
        const shortHash = execFileSync("git", ["rev-parse", "--short", "HEAD"], {
            cwd,
            encoding: "utf8",
            stdio: ["ignore", "pipe", "ignore"],
        }).trim();
        if (!shortHash) {
            return undefined;
        }

        const status = execFileSync("git", ["status", "--porcelain"], {
            cwd,
            encoding: "utf8",
            stdio: ["ignore", "pipe", "ignore"],
        }).trim();
        return `${shortHash}${status.length > 0 ? "?" : ""}`;
    } catch (_error) {
        return undefined;
    }
}
